//! [`Command`], a single registered command.

use std::fmt;
use std::future::Future;
use std::pin::Pin;

use crate::{CommandArgs, CommandError};

/// The boxed async function a [`Command`] runs, over an application context `C`.
pub type CommandFn<C> =
    fn(&C, CommandArgs) -> Pin<Box<dyn Future<Output = Result<(), CommandError>> + Send + '_>>;

/// A registered command, addressed as `<namespace>:<name>`; usually generated by
/// [`#[command]`](macro@fundamental_macros::command).
#[must_use]
pub struct Command<C> {
    namespace: &'static str,
    name: &'static str,
    description: Option<&'static str>,
    run_fn: CommandFn<C>,
}

impl<C> Command<C> {
    /// Creates a command; `description` is the help line `fun run --list` shows.
    pub fn new(
        namespace: &'static str,
        name: &'static str,
        description: Option<&'static str>,
        run_fn: CommandFn<C>,
    ) -> Self {
        Self {
            namespace,
            name,
            description,
            run_fn,
        }
    }

    /// The command's namespace — the first half of its address.
    #[must_use]
    pub fn namespace(&self) -> &'static str {
        self.namespace
    }

    /// The command's name within its namespace.
    #[must_use]
    pub fn name(&self) -> &'static str {
        self.name
    }

    /// The command's address, `<namespace>:<name>`.
    #[must_use]
    pub fn address(&self) -> String {
        format!("{}:{}", self.namespace, self.name)
    }

    /// The command's one-line description, if it declared one.
    #[must_use]
    pub fn description(&self) -> Option<&'static str> {
        self.description
    }

    /// Runs the command against `ctx` with the passthrough `args`.
    pub(crate) fn run<'a>(
        &self,
        ctx: &'a C,
        args: CommandArgs,
    ) -> Pin<Box<dyn Future<Output = Result<(), CommandError>> + Send + 'a>> {
        (self.run_fn)(ctx, args)
    }
}

impl<C> fmt::Debug for Command<C> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Command")
            .field("namespace", &self.namespace)
            .field("name", &self.name)
            .field("description", &self.description)
            .field("run_fn", &"<fn>")
            .finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accessors_return_the_address_and_description() {
        let command: Command<()> = Command::new("greet", "hello", Some("say hi"), |_ctx, _args| {
            Box::pin(async { Ok(()) })
        });
        assert_eq!(command.namespace(), "greet");
        assert_eq!(command.name(), "hello");
        assert_eq!(command.address(), "greet:hello");
        assert_eq!(command.description(), Some("say hi"));
    }

    #[test]
    fn description_is_optional() {
        let command: Command<()> = Command::new("greet", "bare", None, |_ctx, _args| {
            Box::pin(async { Ok(()) })
        });
        assert_eq!(command.description(), None);
    }

    #[test]
    fn debug_redacts_the_function_pointer() {
        let command: Command<()> = Command::new("greet", "hello", None, |_ctx, _args| {
            Box::pin(async { Ok(()) })
        });
        let rendered = format!("{command:?}");
        assert!(rendered.contains("greet"));
        assert!(rendered.contains("hello"));
        assert!(rendered.contains("<fn>"));
    }

    #[tokio::test]
    #[expect(clippy::excessive_nesting, reason = "readability baseline")]
    async fn run_forwards_context_and_args() {
        use std::sync::Mutex;

        struct Ctx {
            seen: Mutex<Vec<String>>,
        }

        let command: Command<Ctx> =
            Command::new("test", "echo", None, |ctx: &Ctx, args: CommandArgs| {
                Box::pin(async move {
                    ctx.seen.lock().unwrap().extend(args.into_vec());
                    Ok(())
                })
            });

        let ctx = Ctx {
            seen: Mutex::new(Vec::new()),
        };
        command
            .run(&ctx, CommandArgs::new(["a".to_string(), "b".to_string()]))
            .await
            .expect("command succeeds");
        assert_eq!(*ctx.seen.lock().unwrap(), vec!["a", "b"]);
    }
}
